/**
 * Settings → 元构法典: the law's own tables, rendered from the document.
 *
 * The axioms and properties are parsed out of `$DSH_HOME/AGENTS.md` at request
 * time rather than hard-coded, because the upstream project ships several
 * mutually inconsistent counters for them (its own CONSTITUTION files disagree
 * with their own tables). Showing the document's own rows is the only honest read.
 *
 * @module metago-lifeform-dsh/client/CodexSection
 */

import * as styles from './surface.module.css'
import { useMetago, Row, Badge, ErrorBox, Loading } from './ui.js'

/** The codex page body. */
export function CodexSection() {
  const status = useMetago('law', 0)
  const data = status.data

  return (
    <div className={styles.stack}>
      <section className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>元构法典</h2>
          <Badge tone={data ? 'ok' : 'idle'}>{data ? `V${data.version}` : '读取中'}</Badge>
        </div>
        <p className={styles.cardBody}>
          下表逐行取自 $DSH_HOME/AGENTS.md 正文。上游《元构全息智能引擎》蓝本未公开，
          因此 A6–A33 与 D1–D36 只有范围占位、没有正文；这里只呈现有正文的条目，
          不把占位当成条款。
        </p>
      </section>

      {status.state === 'error' ? <ErrorBox message={status.error} /> : null}
      {status.state === 'loading' && data === null ? <Loading /> : null}

      {data ? (
        <>
          <section className={styles.card}>
            <div className={styles.cardHead}>
              <h2 className={styles.cardTitle}>核心公理 · {data.axioms.length} 条有正文</h2>
            </div>
            {data.axioms.length === 0 ? <div className={styles.empty}>未解析到公理表。</div> : (
              <table className={styles.table}>
                <thead>
                  <tr><th>编号</th><th>公理</th><th>运行约束</th></tr>
                </thead>
                <tbody>
                  {data.axioms.map(axiom => (
                    <tr key={axiom.id}>
                      <td className={styles.idCell}>{axiom.id}</td>
                      <td>{axiom.title}</td>
                      <td>{axiom.constraint}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </section>

          <section className={styles.card}>
            <div className={styles.cardHead}>
              <h2 className={styles.cardTitle}>根本属性 · {data.properties.length} 条有正文</h2>
            </div>
            {data.properties.length === 0 ? <div className={styles.empty}>未解析到属性表。</div> : (
              <table className={styles.table}>
                <thead>
                  <tr><th>编号</th><th>属性</th><th>强制行为</th></tr>
                </thead>
                <tbody>
                  {data.properties.map(property => (
                    <tr key={property.id}>
                      <td className={styles.idCell}>{property.id}</td>
                      <td>{property.title}</td>
                      <td>{property.behaviour}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </section>

          <section className={styles.card}>
            <div className={styles.cardHead}>
              <h2 className={styles.cardTitle}>运行协议与门禁</h2>
            </div>
            <div className={styles.rows}>
              <Row label="UDGK 交付门禁" value={data.markers.udgk ? '在位' : '缺'} />
              <Row label="第一性原理公理 A37 / D44" value={data.axioms.some(item => item.id === 'A37') ? '在位' : '缺'} />
              <Row label="对抗式审查公理 A38 / D45" value={data.axioms.some(item => item.id === 'A38') ? '在位' : '缺'} />
              <Row label="架构治理强制规则" value={data.markers.archGovernance ? '在位' : '缺'} />
              <Row label="完整性治理条款" value={data.markers.completeness ? '在位' : '缺'} />
              <Row label="第十八章 MCP 触发协议" value={data.markers.mcpChapter ? '在位' : '缺'} />
              <Row label="第十九章 浏览器自动化" value={data.markers.browserChapter ? '在位' : '缺'} />
              <Row label="第二十章 进程清理铁律" value={data.markers.processLaw ? '在位' : '缺'} />
            </div>
            <p className={styles.footnote}>
              如某一章显示"缺"，说明当前加载的法则被指令预算截断或该版本尚未包含该章。
              元构生命体模式的 Agent preset 把预算提到 262144 B，使完整法则进入上下文。
            </p>
          </section>
        </>
      ) : null}
    </div>
  )
}
