/**
 * metago-lifeform-dsh — browser half.
 *
 * Additive seats, each `risk: none` in the Slot catalog:
 *   1. `main` + `sidebar.panellist` — the 元构控制台 page and its sidebar icon.
 *   2. `settings.section` — the 元构生命体 settings page.
 *   3. `settings.section` — the 元构法典 page.
 *   4. `sidebar.brand.mark` + `conversation.hero.brand.mark` — 自有品牌图标，
 *      外加 branding.css 里的两处文案替换（元智能、构万象 / MetaGO Fabric）。
 *
 * Cross-package contributions are wrapped in `ctx.slots.inject(...)` so the
 * plugin's activation order cannot race the seats it contributes to.
 *
 * @module metago-lifeform-dsh/client
 */

// 副作用导入：全局品牌样式。build.mjs 会把 .css 编译成一个带 data-plugin 标记的
// <style>，在工厂首次运行时注入；这一行就是"样式已注入"的开关。
import './branding/branding.css'

import { PanelPage } from './PanelPage.js'
import { PanelIcon } from './PanelIcon.js'
import { SettingsSection } from './SettingsSection.js'
import { CodexSection } from './CodexSection.js'
import { HeroBrandMark, SidebarBrandMark, SidebarBrandName } from './branding/BrandMark.js'
import { NS, zh, en } from './locales.js'

/** Panel identity; `sidebar.panellist.id` must equal the `main` key. */
export const PANEL_ID = 'metago-lifeform'

/** Cordis client services this plugin needs before it activates. */
export const inject = ['slots', 'layout', 'locale']

/** Register the seats this plugin owns. */
export function apply(ctx) {
  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'metago: dictionaries')
  const t = ctx.locale.bind(NS)

  // ---------------------------------------------------------------- 品牌覆盖
  //
  // 为什么必须显式给一个**更低的 priority**：
  // SlotCore 对 `single` 槽位的规则是——**同一 priority 上已有注册就抛异常**
  // （`single slot "…" already has a registration … register at a different
  // priority to shadow it (lowest renders)`），而**最低 priority 者渲染**。
  // 官方品牌插件 `@deepseek-ai/dsh-client-ui-brand-official` 已经在 priority 0
  // 上占用了这两个侧栏槽位；早前这里用默认（0）注册，于是**直接抛异常、注册根本
  // 没有落地**，界面上依旧是 DeepSeek 的资产。用 -1 才是官方给出的遮蔽方式。
  const SHADOW = -1

  // 侧栏左上角 logo（宿主 fallback 是 FishLogo）。折叠栏与展开行是同一个座位，
  // 组件内部按容器区分尺寸，见 branding.css。
  ctx.slots.inject('sidebar.brand.mark', () => ctx.slots.register({
    name: 'sidebar.brand.mark',
    priority: SHADOW,
  }, SidebarBrandMark))

  // 侧栏 logo 右侧的品牌名。官方插件把 mark 与 name 作为一组同时注册，只换图标会
  // 剩下「[我们的字标] deepseek HARNESS」这种半换品牌的状态，因此一并接管。
  ctx.slots.inject('sidebar.brand.name', () => ctx.slots.register({
    name: 'sidebar.brand.name',
    priority: SHADOW,
  }, SidebarBrandName))

  // 空白会话 Hero 里欢迎语左边的图标（宿主 fallback 是 HeroFish，无官方占用者；
  // 同样给 -1 只是为了让"本插件意图覆盖"这件事在数据上可见）。
  ctx.slots.inject('conversation.hero.brand.mark', () => ctx.slots.register({
    name: 'conversation.hero.brand.mark',
    priority: SHADOW,
  }, HeroBrandMark))

  // The console page, shown in the centre column when the sidebar entry is chosen.
  ctx.slots.inject('main', () => ctx.slots.register({
    name: 'main',
    key: PANEL_ID,
    locale: NS,
  }, PanelPage))

  // The sidebar entry. The shell owns the click; the icon only paints `active`.
  ctx.slots.inject('sidebar.panellist', () => ctx.slots.register({
    name: 'sidebar.panellist',
    id: PANEL_ID,
    order: 2,
    label: () => t('panel'),
    locale: NS,
  }, PanelIcon))

  // Settings → 元构生命体.
  ctx.slots.inject('settings.section', () => ctx.slots.register({
    name: 'settings.section',
    id: 'metago-lifeform',
    order: 40,
    label: () => t('nav'),
    locale: NS,
  }, SettingsSection))

  // Settings → 元构法典.
  ctx.slots.inject('settings.section', () => ctx.slots.register({
    name: 'settings.section',
    id: 'metago-codex',
    order: 41,
    label: () => t('codex'),
    locale: NS,
  }, CodexSection))
}
