/**
 * metago-lifeform-dsh/client/ConsoleViews — 元构控制台 V11 的四个可交互视图
 *
 * 计划 3.1.2 的六个域里，本文件负责：
 *   ③ 治理与门禁（GovernanceView）—— L2/L3 动作按钮
 *   ⑤ 运行运维（OpsView）—— MCP/技能重采 + L3 动作
 *   ⑥ 操作审计（AuditView）—— 审计日志 + 导出
 *
 * 以及公用的 ActionBar：所有动作统一走 POST /api/metago/console/action，
 * L3 动作先 GET /api/metago/console/confirm?action=<id> 取一次性令牌（60s）。
 *
 * @module metago-lifeform-dsh/client/ConsoleViews
 */

import { useState } from 'react'
import * as styles from './panel.module.css'
import { Row, Cell, Badge, ErrorBox, Loading, stamp, humanNum } from './ui.js'

/* ------------------------------------------------------------------ *
 * 动作调用
 * ------------------------------------------------------------------ */

async function callAction(actionId, params, needsConfirm) {
  let confirmToken = ''
  if (needsConfirm) {
    const r = await fetch(`/api/metago/console/confirm?action=${encodeURIComponent(actionId)}`, { headers: { accept: 'application/json' } })
    const j = await r.json()
    if (!j.ok) throw new Error(`取确认令牌失败：${j.error || r.status}`)
    confirmToken = j.token
  }
  const r2 = await fetch('/api/metago/console/action', {
    method: 'POST',
    headers: { 'content-type': 'application/json', accept: 'application/json' },
    body: JSON.stringify({ action: actionId, params: params || {}, confirmToken }),
  })
  const out = await r2.json()
  if (!r2.ok || out.ok === false) throw new Error(out.error || `HTTP ${r2.status}`)
  return out
}

/* ------------------------------------------------------------------ *
 * 动作条
 * ------------------------------------------------------------------ */

/** 一组动作按钮。按 domain 过滤动作注册表。 */
export function ActionBar({ consoleMeta, domain, onDone, presets }) {
  const [busy, setBusy] = useState('')
  const [msg, setMsg] = useState(null)
  if (!consoleMeta) return null
  const actions = consoleMeta.actions.filter((a) => a.domain === domain)
  if (!actions.length) return null

  const run = async (a) => {
    setBusy(a.id)
    setMsg(null)
    try {
      // 没有外部 presets 时用内置默认值：L3 动作必须带合法参数，否则会因缺参失败
      const builtin = {
        'gate.toggleMode': { mode: (consoleMeta && consoleMeta.currentMode) || 'shadow' },
        'memory.recallTest': { query: 'metago', limit: 5 },
        'tool.dryRun': { tool: 'pwsh', args: {} },
        'gate.explain': { tool: 'pwsh' },
        'audit.tail': { limit: 50 },
      }
      const params = presets && presets[a.id] ? presets[a.id]() : (builtin[a.id] || {})
      const out = await callAction(a.id, params, a.needsConfirm)
      const brief = out.checks
        ? `${out.checks.filter((c) => c.pass).length}/${out.checks.length} 项通过`
        : out.hits
          ? `命中 ${out.hits.length} 条`
          : out.mode || out.total || out.note || '成功'
      setMsg({ ok: true, text: `${a.id} → ${brief}` })
      if (onDone) onDone()
    } catch (e) {
      setMsg({ ok: false, text: `${a.id} 失败：${String(e.message || e)}` })
    } finally {
      setBusy('')
    }
  }

  return (
    <div style={{ marginTop: 12 }}>
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
        {actions.map((a) => (
          <button
            key={a.id}
            type="button"
            className={styles.refresh}
            disabled={busy === a.id}
            onClick={() => run(a)}
            title={`${a.level}${a.needsConfirm ? ' · 需一次性确认令牌' : ''} — ${a.desc}`}
          >
            {busy === a.id ? '执行中…' : a.id}
            {a.needsConfirm ? ' 🔒' : ''}
          </button>
        ))}
      </div>
      {msg ? (
        <div style={{ marginTop: 8 }}>
          <Badge tone={msg.ok ? 'ok' : 'bad'}>{msg.text}</Badge>
        </div>
      ) : null}
    </div>
  )
}

/* ------------------------------------------------------------------ *
 * ③ 治理与门禁
 * ------------------------------------------------------------------ */

export function GovernanceView({ data, consoleMeta, onDone }) {
  const [tool, setTool] = useState('pwsh')
  const [explain, setExplain] = useState(null)
  const law = data.law || {}

  const doExplain = async () => {
    setExplain({ loading: true })
    try {
      const out = await callAction('gate.explain', { tool }, false)
      setExplain(out)
    } catch (e) { setExplain({ ok: false, error: String(e.message || e) }) }
  }

  return (
    <>
      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>门禁状态</h2>
          <Badge tone={law.exists ? 'ok' : 'bad'}>{law.exists ? `法则 V${law.version}` : '法则缺失'}</Badge>
        </div>
        <div>
          <Row label="法则版本" value={law.version ? `V${law.version}` : '—'} mono />
          <Row label="法则体积" value={law.bytes == null ? '—' : `${humanNum(law.bytes)} B`} mono />
          <Row label="章节" value={law.chapterCount == null ? '—' : `${law.chapterCount} 编号 / ${law.headingCount == null ? '—' : law.headingCount} 标题`} mono />
          <Row label="公理 / 属性" value={`${(law.axioms || []).length} / ${(law.properties || []).length}`} mono />
          <Row label="L4 黑名单" value={(consoleMeta && consoleMeta.l4Blocked ? consoleMeta.l4Blocked.join(' · ') : '—')} />
        </div>
        <ActionBar consoleMeta={consoleMeta} domain="governance" onDone={onDone} />
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>解释一个工具的风险判定</h2>
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
          <input
            type="text"
            value={tool}
            onChange={(e) => setTool(e.target.value)}
            placeholder="工具名，如 pwsh / read / metago_atom"
            style={{ padding: '6px 10px', borderRadius: 6, border: '1px solid #30363d', background: '#0d1117', color: '#e6edf3', minWidth: 260 }}
          />
          <button type="button" className={styles.refresh} onClick={doExplain}>解释</button>
        </div>
        {explain ? (
          <div style={{ marginTop: 10 }}>
            {explain.loading ? <Loading /> : explain.ok === false ? <ErrorBox message={explain.error} /> : (
              <>
                <Row label="工具" value={explain.tool} mono />
                <Row label="等级" value={explain.level} mono />
                <Row label="命中规则" value={explain.matchedRule} />
                <Row label="当前模式" value={explain.mode} mono />
              </>
            )}
          </div>
        ) : null}
      </div>
    </>
  )
}

/* ------------------------------------------------------------------ *
 * ⑤ 运行运维
 * ------------------------------------------------------------------ */

export function OpsView({ data, consoleMeta, onDone }) {
  const mcp = data.mcp || {}
  const skills = data.skills || {}
  const packages = data.packages || {}
  return (
    <>
      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>MCP 与技能</h2>
          <Badge tone={mcp.mounted ? 'ok' : 'warn'}>{mcp.mounted ? '已挂载' : '未挂载'}</Badge>
        </div>
        <div>
          <Row label="MCP 工具" value={`${mcp.total || 0} 个`} mono />
          <Row label="服务器" value={(mcp.servers || []).map((s) => `${s.server}=${s.count}`).join(' / ') || '—'} mono />
          <Row label="技能（全部）" value={`${skills.total || 0} 个`} mono />
          <Row label="技能（metago-*）" value={`${skills.metago || 0} 个`} mono />
          <Row label="触发词" value={`${skills.triggerCount || 0} 条`} mono />
          <Row label="引擎" value={packages.engine && packages.engine.installed ? `v${packages.engine.version}` : '未安装'} mono />
          <Row label="算法" value={packages.algorithms && packages.algorithms.installed ? `v${packages.algorithms.version}` : '未安装'} mono />
        </div>
        <ActionBar consoleMeta={consoleMeta} domain="ops" onDone={onDone} />
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>审计与确认</h2>
        </div>
        <div>
          <Row label="审计文件" value={consoleMeta ? consoleMeta.auditPath : '—'} mono />
          <Row label="确认令牌有效期" value={consoleMeta ? `${consoleMeta.confirmTtlMs} ms` : '—'} mono />
          <Row label="动作总数" value={consoleMeta ? `${consoleMeta.actions.length} 个` : '—'} mono />
        </div>
      </div>
    </>
  )
}

/* ------------------------------------------------------------------ *
 * ⑥ 操作审计
 * ------------------------------------------------------------------ */

export function AuditView({ consoleMeta }) {
  const [data, setData] = useState(null)
  const [err, setErr] = useState(null)
  const [loading, setLoading] = useState(false)

  const load = async () => {
    setLoading(true)
    setErr(null)
    try {
      const r = await fetch('/api/metago/console/audit?limit=200', { headers: { accept: 'application/json' } })
      const j = await r.json()
      if (!r.ok || j.ok === false) throw new Error(j.error || `HTTP ${r.status}`)
      setData(j)
    } catch (e) { setErr(String(e.message || e)) } finally { setLoading(false) }
  }
  if (!data && !loading && !err) load()

  const exportJsonl = () => {
    const lines = (data && data.lines ? data.lines : []).map((l) => JSON.stringify(l)).join('\n')
    const blob = new Blob([lines], { type: 'application/x-ndjson' })
    const a = document.createElement('a')
    a.href = URL.createObjectURL(blob)
    a.download = `console-audit-${Date.now()}.jsonl`
    a.click()
    setTimeout(() => URL.revokeObjectURL(a.href), 3000)
  }

  return (
    <div className={styles.card}>
      <div className={styles.cardHead}>
        <h2 className={styles.cardTitle}>操作审计</h2>
        <Badge tone="ok">{data ? `${data.total} 条` : '—'}</Badge>
      </div>
      <div style={{ display: 'flex', gap: 8, marginBottom: 10 }}>
        <button type="button" className={styles.refresh} onClick={load} disabled={loading}>{loading ? '读取中…' : '刷新'}</button>
        <button type="button" className={styles.refresh} onClick={exportJsonl} disabled={!data || !data.lines.length}>导出 JSONL</button>
      </div>
      {err ? <ErrorBox message={err} /> : null}
      {loading ? <Loading /> : null}
      {data && data.lines && data.lines.length === 0 ? (
        <p style={{ color: '#8b949e' }}>还没有动作记录。去「治理与门禁」点几次动作就会出现在这里。</p>
      ) : null}
      {data && data.lines && data.lines.length > 0 ? (
        <div style={{ maxHeight: 420, overflow: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
            <thead>
              <tr style={{ textAlign: 'left', color: '#8b949e' }}>
                <th style={{ padding: '4px 6px' }}>时间</th>
                <th style={{ padding: '4px 6px' }}>动作</th>
                <th style={{ padding: '4px 6px' }}>级别</th>
                <th style={{ padding: '4px 6px' }}>结果</th>
                <th style={{ padding: '4px 6px' }}>回滚点</th>
              </tr>
            </thead>
            <tbody>
              {data.lines.map((l, i) => (
                <tr key={i} style={{ borderTop: '1px solid #21262d' }}>
                  <td style={{ padding: '4px 6px', fontFamily: 'monospace' }}>{stamp(l.ts)}</td>
                  <td style={{ padding: '4px 6px', fontFamily: 'monospace' }}>{l.action || '—'}</td>
                  <td style={{ padding: '4px 6px', fontFamily: 'monospace' }}>{l.level || '—'}</td>
                  <td style={{ padding: '4px 6px' }}>
                    <Badge tone={l.result === 'ok' ? 'ok' : 'bad'}>{l.result || (l.ok ? 'ok' : 'fail')}</Badge>
                    {l.error ? <span style={{ color: '#f85149', marginLeft: 6 }}>{String(l.error).slice(0, 40)}</span> : null}
                  </td>
                  <td style={{ padding: '4px 6px', fontFamily: 'monospace', color: '#8b949e' }}>{l.rollbackPoint || '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : null}
    </div>
  )
}
