/**
 * The sidebar seat's icon. Owner props are `{ size, active }`; the click is
 * owned by the shell, which calls `ctx.layout.selectPanel` — this component
 * only paints state.
 *
 * @module metago-lifeform-dsh/client/PanelIcon
 */

import * as styles from './icon.module.css'

/**
 * @param props - `size` from the seat, `active` while this panel is shown.
 */
export function PanelIcon({ size = 16, active = false }) {
  return (
    <span
      className={styles.icon}
      data-active={active ? '' : undefined}
      style={{ width: size, height: size }}
      aria-hidden="true"
    >
      <svg viewBox="0 0 16 16" width={size} height={size} fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round">
        {/* 三层架构：驱动层 / 控制层 / 执行层 */}
        <path d="M8 1.6 14 4.6 8 7.6 2 4.6Z" />
        <path d="M2 8.1 8 11.1 14 8.1" />
        <path d="M2 11.4 8 14.4 14 11.4" />
      </svg>
    </span>
  )
}
