/**
 * The 元构控制台 panel — the sidebar seat's centred page.
 *
 * Four read-only views over the live installation. Every value comes from the
 * plugin's host half, which reads the real artifacts; the panel never derives a
 * number the host cannot prove.
 *
 * @module metago-lifeform-dsh/client/PanelPage
 */

import { useState } from 'react'
import * as styles from './panel.module.css'
import { useMetago, Row, Cell, Bar, Badge, ErrorBox, Loading, stamp, humanBytes, humanNum, healthBand, serverLabel } from './ui.js'
import { GovernanceView, OpsView, AuditView, ActionBar } from './ConsoleViews.js'

/** 六个域（计划 3.1.2）。法典并入总览，不再单独占一个 tab。 */
const TABS = [
  { id: 'overview', label: '总览 Live' },
  { id: 'capability', label: '能力浏览器' },
  { id: 'governance', label: '治理与门禁' },
  { id: 'memory', label: '记忆与知识' },
  { id: 'ops', label: '运行运维' },
  { id: 'audit', label: '操作审计' },
]

/** The panel body. */
export function PanelPage() {
  const [tab, setTab] = useState('overview')
  const [reloadKey, setReloadKey] = useState(0)
  // V11：数据源改为 console/snapshot（一次拿状态 + 动作注册表）
  const snap = useMetago('console/snapshot', reloadKey)
  const status = snap.data && snap.data.status ? { state: snap.state, data: snap.data.status, error: snap.error } : snap
  const consoleMeta = (snap.data && snap.data.console) || null

  return (
    <section className={styles.root}>
      <header className={styles.header}>
        <div>
          <h1 className={styles.title}>元构控制台</h1>
          <p className={styles.subtitle}>
            MetaGO Fabric V11 · 元构超级智能生命体模式套件 · 驭智层
          </p>
        </div>
        <button type="button" className={styles.refresh} onClick={() => setReloadKey(value => value + 1)}>
          重新体检
        </button>
      </header>

      <nav className={styles.tabs} role="tablist">
        {TABS.map(entry => (
          <button
            key={entry.id}
            type="button"
            role="tab"
            aria-selected={tab === entry.id}
            className={styles.tab}
            data-active={tab === entry.id ? '' : undefined}
            onClick={() => setTab(entry.id)}
          >
            {entry.label}
          </button>
        ))}
      </nav>

      {status.state === 'loading' && status.data === null ? <Loading /> : null}
      {status.state === 'error' ? <ErrorBox message={status.error} /> : null}
      {status.data ? (
        <>
          {tab === 'overview' ? (
            <>
              <Overview data={status.data} />
              <LawView data={status.data} />
            </>
          ) : null}
          {tab === 'capability' ? <><CapabilityView data={status.data} consoleMeta={consoleMeta} onDone={() => setReloadKey(v => v + 1)} /><div className={styles.card}><div className={styles.cardHead}><h2 className={styles.cardTitle}>能力动作</h2></div><ActionBar consoleMeta={consoleMeta} domain="capability" onDone={() => setReloadKey(v => v + 1)} /></div></> : null}
          {tab === 'governance' ? <GovernanceView data={status.data} consoleMeta={consoleMeta} onDone={() => setReloadKey(v => v + 1)} /> : null}
          {tab === 'memory' ? <><MemoryView data={status.data} consoleMeta={consoleMeta} onDone={() => setReloadKey(v => v + 1)} /><div className={styles.card}><div className={styles.cardHead}><h2 className={styles.cardTitle}>记忆动作</h2></div><ActionBar consoleMeta={consoleMeta} domain="memory" onDone={() => setReloadKey(v => v + 1)} /></div></> : null}
          {tab === 'ops' ? <OpsView data={status.data} consoleMeta={consoleMeta} onDone={() => setReloadKey(v => v + 1)} /> : null}
          {tab === 'audit' ? <AuditView consoleMeta={consoleMeta} /> : null}
        </>
      ) : null}

      <p className={styles.footnote}>
        数据源：/api/metago/console/snapshot · 采集时间 {stamp(snap.data && snap.data.ts)} · 动作 {consoleMeta ? consoleMeta.actions.length : 0} 个 / 6 域 · L4（删记忆·改法则·卸插件·清库）一律不给入口
      </p>
    </section>
  )
}

/** Five-layer health plus the headline counters. */
function Overview({ data }) {
  const lawTone = data.law.exists ? (data.lawBudget.fits ? 'ok' : 'bad') : 'bad'
  const memory = data.memory || {}
  const band = healthBand(memory.health, memory.total)
  const algorithms = data.algorithms || {}
  const executable = algorithms.executable ?? 0
  const registered = algorithms.registered ?? 0
  const ratio = registered > 0 ? executable / registered : 0
  const coverage = registered === 0
    ? { label: '未扫描', tone: 'idle' }
    : ratio >= 0.95 ? { label: '基本完整', tone: 'ok' }
      : ratio >= 0.7 ? { label: '可用', tone: 'ok' }
        : { label: '待补', tone: 'warn' }
  const tierLine = ['T1', 'T2', 'T3']
    .filter(tier => algorithms.byTier && algorithms.byTier[tier])
    .map(tier => `${tier} ${algorithms.byTier[tier].total}/${algorithms.byTier[tier].ok}`)
    .join(' · ')

  return (
    <>
      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>三层架构 · 五层闭环</h2>
          <Badge tone={data.law.exists && data.mcp.mounted ? 'ok' : 'warn'}>
            {data.law.exists && data.mcp.mounted ? '在位' : '待补齐'}
          </Badge>
        </div>
        <div className={styles.layers}>
          {[
            { state: data.law.exists ? 'live' : 'idle', label: '驱动层 · 法则', detail: `${data.law.lines} 行 · ${data.law.chapterCount} 章` },
            { state: data.skills.metago > 0 ? 'live' : 'idle', label: '能力层 · 技能', detail: `${data.skills.metago} 技能 · ${data.skills.triggerCount} 触发词` },
            { state: data.mcp.mounted ? 'live' : 'idle', label: '执行层 · 工具', detail: `${data.mcp.total} 个 MCP 工具` },
            { state: data.packages && data.packages.engine.installed ? 'live' : 'idle', label: '进化层 · 引擎', detail: data.packages && data.packages.engine.version ? `v${data.packages.engine.version}` : '未安装' },
            { state: memory.exists ? 'live' : 'idle', label: '记忆层 · KMWI', detail: `H = ${memory.health === undefined ? '—' : memory.health} / 100 · ${humanNum(memory.total)} 条` },
          ].map(layer => (
            <div className={styles.layer} key={layer.label}>
              <span className={styles.dot} data-state={layer.state} />
              <span className={styles.layerLabel}>{layer.label}</span>
              <span className={styles.mono}>{layer.detail}</span>
            </div>
          ))}
        </div>
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>法则加载预算</h2>
          <Badge tone={lawTone}>{data.lawBudget.fits ? '全文可加载' : '将被截断'}</Badge>
        </div>
        <Row label="法则版本" value={data.law.version ? `V${data.law.version}` : '—'} mono />
        <Row label="文件大小" value={`${humanBytes(data.law.bytes)} / ${humanBytes(data.lawBudget.configured)}`} mono />
        <Row label="SHA-256" value={data.law.sha256 ? data.law.sha256.slice(0, 16) + '…' : '—'} mono />
        <Row label="章节 / 行数" value={`${data.law.chapterCount} / ${humanNum(data.law.lines)}`} mono />
        <Bar ratio={data.lawBudget.configured ? data.law.bytes / data.lawBudget.configured : 0} tone={lawTone} />
        <p className={styles.footnote}>{data.lawBudget.note}</p>
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>四层记忆 KMWI</h2>
          <Badge tone={band.tone}>{band.label}</Badge>
        </div>
        <Row label="存储位置" value={memory.path || '—'} mono />
        <Row label="状态" value={memory.exists ? `已落盘 · ${humanBytes(memory.bytes)}` : '未落盘'} />
        <Row label="晋升历史" value={humanNum(memory.history)} mono />
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>运行时</h2>
        </div>
        <div className={styles.grid}>
          <Cell label="Node" value={data.runtime.node} />
          <Cell label="平台" value={data.runtime.platform} />
          <Cell label="MCP 工具" value={humanNum(data.mcp.total)} />
          <Cell label="技能" value={humanNum(data.skills.metago)} />
          <Cell label="触发词" value={humanNum(data.skills.triggerCount)} />
          <Cell label="调用台账" value={data.runtime.log && data.runtime.log.calls.exists ? humanNum(data.runtime.log.calls.records) : '—'} />
        </div>
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>算法库</h2>
          {/* Registry size and executable size are different numbers, and showing
              only the registry's flattered the library by 4x. Both are shown. */}
          <Badge tone={coverage.tone}>{coverage.label}</Badge>
        </div>
        <div className={styles.grid}>
          <Cell label="注册总数" value={humanNum(algorithms.registered)} />
          <Cell label="实测可执行" value={humanNum(algorithms.executable)} />
          <Cell label="未实现" value={humanNum(algorithms.notImplemented)} />
          <Cell label="待修（输入/接口）" value={humanNum(algorithms.errors + algorithms.invalid)} />
        </div>
        <Row label="分层：注册 / 可执行" value={tierLine} mono />
        <Row label="覆盖数据来源" value={algorithms.source === 'absent' ? '未扫描' : 'verify-algorithms-all.mjs'} mono />
        {(algorithms.topFailureReasons || []).slice(0, 3).map(row => (
          <Row key={row.reason} label={row.reason.slice(0, 42)} value={`${row.count} 个`} mono />
        ))}
      </div>
    </>
  )
}

/** The law codex: chapters, axioms and properties read out of the document. */
function LawView({ data }) {
  const axioms = data.law.axioms || []
  const properties = data.law.properties || []
  const chapters = data.law.chapters || []

  return (
    <>
      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>核心公理（有正文 {axioms.length} 条）</h2>
          <Badge tone="ok">A 系</Badge>
        </div>
        {axioms.length === 0 ? <div className={styles.empty}>未从法则文件中解析到公理表。</div> : null}
        {axioms.map(axiom => (
          <Row key={axiom.id} label={`${axiom.id} · ${axiom.title}`} value={axiom.constraint || '—'} />
        ))}
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>根本属性（有正文 {properties.length} 条）</h2>
          <Badge tone="ok">D 系</Badge>
        </div>
        {properties.length === 0 ? <div className={styles.empty}>未从法则文件中解析到属性表。</div> : null}
        {properties.map(property => (
          <Row key={property.id} label={`${property.id} · ${property.title}`} value={property.behaviour || '—'} />
        ))}
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>章节目录（{chapters.length}）</h2>
        </div>
        <div className={styles.rows}>
          {chapters.map(chapter => (
            <div className={styles.row} key={chapter.title}>
              <span className={styles.rowKey}>{chapter.title}</span>
            </div>
          ))}
        </div>
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>治理标记</h2>
        </div>
        <div className={styles.grid}>
          <Cell label="UDGK 交付门禁" value={data.law.markers.udgk ? '在位' : '缺'} />
          <Cell label="架构治理条款" value={data.law.markers.archGovernance ? '在位' : '缺'} />
          <Cell label="完整性治理条款" value={data.law.markers.completeness ? '在位' : '缺'} />
          <Cell label="第十八章 MCP" value={data.law.markers.mcpChapter ? '在位' : '缺'} />
          <Cell label="第十九章 浏览器" value={data.law.markers.browserChapter ? '在位' : '缺'} />
          <Cell label="第二十章 进程铁律" value={data.law.markers.processLaw ? '在位' : '缺'} />
        </div>
      </div>
    </>
  )
}

/** Skills, MCP tools and the engine's package inventory. */
function CapabilityView({ data, consoleMeta, onDone }) {
  const families = data.skills.families || []
  const servers = data.mcp.servers || []
  const packages = data.packages || {}

  return (
    <>
      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>MCP 工具（{humanNum(data.mcp.total)}）</h2>
          <Badge tone={data.mcp.mounted ? 'ok' : 'bad'}>{data.mcp.mounted ? '已挂载' : '未挂载'}</Badge>
        </div>
        {servers.length === 0 ? <div className={styles.empty}>当前组合没有挂载任何 MCP 服务器。</div> : null}
        {servers.map(server => (
          <Row key={server.server} label={serverLabel(server.server)} value={humanNum(server.count)} mono />
        ))}
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>技能目录</h2>
          <Badge tone={data.skills.metago > 0 ? 'ok' : 'bad'}>
            {data.skills.metago} / {data.skills.total}
          </Badge>
        </div>
        <Row label="带触发的技能" value={`${data.skills.withTrigger} / ${data.skills.metago}`} mono />
        <Row label="去重触发词" value={humanNum(data.skills.triggerCount)} mono />
        <Row label="目录" value={data.skills.dir} mono />
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>能力族分布</h2>
        </div>
        <div className={styles.grid}>
          {families.slice(0, 24).map(family => (
            <Cell key={family.name} label={family.name} value={family.count} />
          ))}
        </div>
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>@metago-ai 引擎包</h2>
        </div>
        {[
          ['引擎 engine', packages.engine],
          ['MCP 服务器 mcp-server', packages.mcpServer],
          ['算法集 algorithms', packages.algorithms],
          ['验证套件 verify-kit', packages.verifyKit],
          ['开发套件 dev-kit', packages.devKit],
        ].map(([label, info]) => (
          <Row
            key={label}
            label={label}
            value={info && info.installed ? `v${info.version}` : '未安装'}
            mono
          />
        ))}
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>MCP 调用台账</h2>
        </div>
        <Row label="日志目录" value={(data.runtime.log && data.runtime.log.dir) || '—'} mono />
        <Row label="calls.jsonl" value={data.runtime.log && data.runtime.log.calls.exists ? `${humanNum(data.runtime.log.calls.records)} 条 · ${humanBytes(data.runtime.log.calls.bytes)}` : '未生成'} mono />
        <Row label="错误记录" value={data.runtime.log ? humanNum(data.runtime.log.calls.errors) : '—'} mono />
        <Row label="最近时间" value={stamp(data.runtime.log && data.runtime.log.lastTs)} mono />
      </div>
    </>
  )
}

/** The four-layer memory store in detail. */
function MemoryView({ data, consoleMeta, onDone }) {
  const memory = data.memory || {}
  const layers = memory.layers || { K: 0, M: 0, W: 0, I: 0 }
  const max = Math.max(1, layers.K, layers.M, layers.W, layers.I)
  const band = healthBand(memory.health, memory.total)
  const flow = [
    ['K · 知识 Knowledge', layers.K],
    ['M · 记忆 Memory', layers.M],
    ['W · 智慧 Wisdom', layers.W],
    ['I · 直觉 Intuition', layers.I],
  ]
  const scores = memory.layerScores || null

  return (
    <>
      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>KMWI 四层</h2>
          <Badge tone={band.tone}>{band.label}</Badge>
        </div>
        {flow.map(([label, count]) => {
          const score = scores ? scores[label.slice(0, 1)] : undefined
          return (
            <div className={styles.memoryRow} key={label}>
              <span className={styles.memoryName}>{label}</span>
              <span className={styles.memoryTrack}>
                <span className={styles.memoryFill} style={{ width: `${(count / max) * 100}%` }} />
              </span>
              <span className={styles.memoryCount}>{score === undefined ? humanNum(count) : `${score}分`}</span>
            </div>
          )
        })}
        <Row label="条目总数" value={humanNum(memory.total)} mono />
        <Row label="综合健康度 H" value={`${memory.health === undefined ? '—' : memory.health} / 100`} mono />
        <Row label="健康度来源" value={memory.healthSource || '—'} mono />
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>存储事实</h2>
        </div>
        <Row label="路径" value={memory.path || '—'} mono />
        <Row label="存在" value={memory.exists ? '是' : '否'} />
        <Row label="大小" value={humanBytes(memory.bytes)} mono />
        <Row label="快照版本" value={memory.version || '—'} mono />
        <Row label="快照时间" value={stamp(memory.timestamp)} mono />
        <Row label="晋升历史" value={humanNum(memory.history)} mono />
        {memory.note ? <p className={styles.footnote}>{memory.note}</p> : null}
        {memory.parseError ? <p className={styles.footnote}>解析失败：{memory.parseError}</p> : null}
      </div>

      <div className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>双流说明</h2>
        </div>
        <p className={styles.footnote}>
          转化流 K → M → W → I：知识经反复使用沉淀为记忆，记忆归纳为智慧，智慧内化为直觉。
          反哺流 I → W → M → K：直觉被验证后回写智慧，智慧失败后回退为记忆，记忆失效后回退为知识。
          引擎的存储路径默认跟随进程工作目录，本插件把本机权威路径固定到 $DSH_HOME 下并在此如实呈现。
        </p>
      </div>
    </>
  )
}
