/**
 * 品牌图标组件：把宿主默认的鱼形 logo 换成自有素材。
 *
 * 两处座位（都是 `single` 槽位，占用即覆盖宿主的 fallback）：
 *   - `sidebar.brand.mark`          → 侧栏左上角 logo（宿主 fallback 是 FishLogo）
 *   - `conversation.hero.brand.mark` → 空白会话 Hero 里欢迎语左边的图标（fallback 是 HeroFish）
 *
 * 尺寸与容器约束（均由宿主 CSS 决定，见 branding.css 的注释）：
 *   - 侧栏折叠栏的座位只有 24px 见方，横向字标按 `contain` 缩进框内，不撑破布局；
 *   - 侧栏展开行高 24px，字标按高度铺开并设上限，避免与右侧的品牌名争位。
 *
 * 两张素材都是透明底，因此不使用圆形裁切 —— 裁切会切掉主体边缘。
 * 图片本身不参与交互（`pointer-events: none`），以免挡住 logoRow 的窗口拖拽
 * 区域与 Hero 图标的 hover 动画热区。
 *
 * @module metago-lifeform-dsh/client/branding/BrandMark
 */

import { HERO_DATA_URI, WORDMARK_DATA_URI } from './brand-assets.js'

/**
 * 侧栏左上角品牌标（折叠栏与展开行共用同一个座位）。
 *
 * 座位契约 `SidebarBrandMarkOwnerProps` 只提供 `size`（方形边长）。
 *
 * @param props - 座位传入的 `size`（宿主传 24）。
 */
export function SidebarBrandMark({ size = 24 }) {
  return (
    <img
      className="meta-brand-wordmark"
      src={WORDMARK_DATA_URI}
      alt=""
      aria-hidden="true"
      draggable={false}
      data-brand-size={size}
    />
  )
}

/**
 * Hero（空白会话）里欢迎语左侧的品牌图标。
 *
 * 座位契约 `HeroBrandMarkOwnerProps` 提供 `size` 与可选的 `className`。
 * **`className` 必须透传到宿主元素上**：它承载着"所在位置标记的几何"——
 * 宿主的 `._Hqq-bq_fish` 规则（transform-origin / display / overflow）以及
 * hover 时的游动动画都挂在这个类上。不透传的话图标仍能显示，但会丢掉这些
 * 宿主行为，与原 fallback 的表现不一致。
 *
 * **尺寸按 3 倍渲染**：宿主给的是 34px（原鱼形图标的方形边长），而这幅插画的主体
 * 只占画面中部约 80%，按 34px 显示视觉上明显偏小。倍数演进：1× → 2×（用户看过）
 * → 3×（当前，即再放大 1.5 倍）。素材是 128×128，3 倍显示约 102px，
 * 像素密度约 1.25 倍，仍不算糊；若要继续放大，建议同步把素材重采样到更高分辨率。
 *
 * @param props - 座位传入的 `size`（宿主传 34）与 `className`。
 */
export function HeroBrandMark({ size = 34, className }) {
  const edge = size * 3
  return (
    <img
      className={className === undefined ? 'meta-brand-hero' : `meta-brand-hero ${className}`}
      src={HERO_DATA_URI}
      alt=""
      aria-hidden="true"
      draggable={false}
      width={edge}
      height={edge}
      data-host-size={size}
    />
  )
}

/**
 * 侧栏品牌名（展开品牌行里 logo 右侧那串文字）。
 *
 * 为什么本插件要一并占用它：官方品牌插件把 `sidebar.brand.mark` 与
 * `sidebar.brand.name` **作为一组同时注册**，两者都渲染 DeepSeek 的品牌资产。
 * 只换图标的话，侧栏会变成「[我们的字标] deepseek HARNESS」——半换品牌比不换更难看，
 * 因此这里一并接管。
 *
 * 文案沿用本项目自己的命名（与 Hero 徽标一致），不引入新造词。
 */
export function SidebarBrandName() {
  return <span className="meta-brand-name">MetaGO Fabric</span>
}
