/**
 * Settings → 元构生命体: the plugin's own page.
 *
 * Reports the facts a user needs to trust the installation — where the law
 * comes from, whether it fits the active preset's budget, which capabilities
 * are mounted, and what the plugin does and does not do — plus a live re-check.
 *
 * @module metago-lifeform-dsh/client/SettingsSection
 */

import { useState } from 'react'
import * as styles from './surface.module.css'
import { useMetago, Row, Cell, Badge, ErrorBox, Loading, humanBytes, humanNum, serverLabel, healthBand } from './ui.js'

/** The settings page body. */
export function SettingsSection() {
  const [reloadKey, setReloadKey] = useState(0)
  const status = useMetago('status', reloadKey)
  const data = status.data
  const band = data ? healthBand(data.memory && data.memory.health, data.memory && data.memory.total) : { label: '', tone: 'idle' }

  return (
    <div className={styles.stack}>
      <section className={styles.card}>
        <div className={styles.cardHead}>
          <h2 className={styles.cardTitle}>元构生命体 · 本机体检</h2>
          <Badge tone={data && data.law.exists && data.mcp.mounted ? 'ok' : 'warn'}>
            {data && data.law.exists && data.mcp.mounted ? '在位' : status.state === 'loading' ? '读取中' : '待补齐'}
          </Badge>
        </div>
        <p className={styles.cardBody}>
          MetaGO Fabric V11（元构超级智能生命体模式套件 · 驭智层）把法则、技能、工具与记忆合成一条闭环。
          本页只读展示本机实际装配了什么；所有数字都由插件宿主半在每次打开时实读磁盘与运行时得到。
        </p>
        <div className={styles.rows} style={{ marginTop: 12 }}>
          <button
            type="button"
            className={styles.badge}
            onClick={() => setReloadKey(value => value + 1)}
            style={{ alignSelf: 'flex-start', cursor: 'pointer' }}
          >
            重新体检
          </button>
        </div>
      </section>

      {status.state === 'error' ? <ErrorBox message={status.error} /> : null}
      {status.state === 'loading' && data === null ? <Loading /> : null}

      {data ? (
        <>
          <section className={styles.card}>
            <div className={styles.cardHead}>
              <h2 className={styles.cardTitle}>法则</h2>
              <Badge tone={data.lawBudget.fits ? 'ok' : 'bad'}>
                {data.lawBudget.fits ? '全文可加载' : `将截断 ${humanBytes(data.lawBudget.truncatedBy)}`}
              </Badge>
            </div>
            <Row label="路径" value={data.law.path} mono />
            <Row label="版本" value={data.law.version ? `V${data.law.version}` : '—'} mono />
            <Row label="大小 / 预算" value={`${humanBytes(data.law.bytes)} / ${humanBytes(data.lawBudget.configured)}`} mono />
            <Row label="行数 / 章节" value={`${humanNum(data.law.lines)} / ${data.law.chapterCount}`} mono />
            <Row label="公理 / 属性（有正文）" value={`${data.law.axioms.length} / ${data.law.properties.length}`} mono />
            <Row label="SHA-256" value={data.law.sha256 || '—'} mono />
            <p className={styles.footnote}>{data.lawBudget.note}</p>
          </section>

          <section className={styles.card}>
            <div className={styles.cardHead}>
              <h2 className={styles.cardTitle}>能力面</h2>
            </div>
            <div className={styles.grid}>
              <Cell label="元构技能" value={humanNum(data.skills.metago)} />
              <Cell label="技能总数" value={humanNum(data.skills.total)} />
              <Cell label="去重触发词" value={humanNum(data.skills.triggerCount)} />
              <Cell label="MCP 工具" value={humanNum(data.mcp.total)} />
              <Cell label="引擎" value={data.packages.engine.installed ? `v${data.packages.engine.version}` : '未安装'} />
              <Cell label="记忆健康 H" value={data.memory.health === undefined ? '—' : `${data.memory.health} / 100`} />
              <Cell label="记忆条目" value={humanNum(data.memory.total)} />
            </div>
            <div className={styles.rows} style={{ marginTop: 12 }}>
              {(data.mcp.servers || []).map(server => (
                <Row key={server.server} label={serverLabel(server.server)} value={humanNum(server.count)} mono />
              ))}
              <Row label="记忆状态" value={data.memory.exists ? `已落盘 · ${band.label}` : '未落盘'} />
            </div>
          </section>

          <section className={styles.card}>
            <div className={styles.cardHead}>
              <h2 className={styles.cardTitle}>插件边界（诚实声明）</h2>
            </div>
            <p className={styles.cardBody}>
              本插件是只读观测面 + 一条状态工具，不代理任何元构执行。它不会：
              替模型决定何时调用元构工具（由法则与触发协议决定）、修改法则或技能文件、
              写入 KMWI 存储、或代替 MCP 服务器执行算法。
              它只做三件事：把本机真实装配状态读出来、把法则表格解析成可读页面、把 112 个工具和 100 个技能的存在性变成可核对的事实。
            </p>
            <p className={styles.footnote}>
              插件根目录 {data.plugin.root} · 版本 {data.plugin.version} · Node {data.runtime.node} · {data.runtime.platform}
            </p>
          </section>
        </>
      ) : null}
    </div>
  )
}
