/**
 * Shared presentation helpers for the 元构控制台 surfaces.
 *
 * @module metago-lifeform-dsh/client/ui
 */

import { useEffect, useState } from 'react'

/**
 * Load one host route on mount and keep it refreshable.
 * @param route - Route below `/api/metago`.
 * @param reloadKey - Changing this value re-runs the request.
 * @returns `{ state, data, error }` where state is 'loading' | 'ready' | 'error'.
 */
export function useMetago(route, reloadKey) {
  const [state, setState] = useState('loading')
  const [data, setData] = useState(null)
  const [error, setError] = useState(null)

  useEffect(() => {
    const controller = new AbortController()
    let live = true
    setState('loading')
    fetch(`/api/metago/${route}`, { signal: controller.signal, headers: { accept: 'application/json' } })
      .then(async response => {
        const text = await response.text()
        let payload
        try {
          payload = JSON.parse(text)
        } catch {
          throw new Error(`响应不是 JSON（HTTP ${response.status}）`)
        }
        if (!response.ok || payload.ok === false) throw new Error(payload && payload.error ? payload.error : `HTTP ${response.status}`)
        return payload
      })
      .then(payload => {
        if (!live) return
        setData(payload)
        setError(null)
        setState('ready')
      })
      .catch(caught => {
        if (!live || caught.name === 'AbortError') return
        setError(String((caught && caught.message) || caught))
        setState('error')
      })
    return () => {
      live = false
      controller.abort()
    }
  }, [route, reloadKey])

  return { state, data, error }
}

/** One label/value row. */
export function Row({ label, value, mono }) {
  return (
    <div className="row" style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 12 }}>
      <span className="rowKey">{label}</span>
      <span className={mono ? 'rowValue mono' : 'rowValue'}>{value}</span>
    </div>
  )
}

/** One small metric cell. */
export function Cell({ label, value }) {
  return (
    <div className="cell">
      <div className="cellKey">{label}</div>
      <div className="cellValue">{value}</div>
    </div>
  )
}

/** A filled proportion bar. */
export function Bar({ ratio, tone }) {
  const width = `${Math.max(0, Math.min(1, Number.isFinite(ratio) ? ratio : 0)) * 100}%`
  return (
    <div className="bar">
      <div className="barFill" data-tone={tone || 'ok'} style={{ width }} />
    </div>
  )
}

/** A status badge. */
export function Badge({ tone, children }) {
  return <span className="badge" data-tone={tone || 'idle'}>{children}</span>
}

/** The failure state every surface shares. */
export function ErrorBox({ message }) {
  return <div className="error">元构状态读取失败：{message}</div>
}

/** The loading state every surface shares. */
export function Loading() {
  return <div className="empty">正在读取元构运行时状态…</div>
}

/** Format an ISO timestamp for display. */
export function stamp(iso) {
  if (!iso) return '—'
  const date = new Date(iso)
  if (Number.isNaN(date.getTime())) return String(iso)
  const pad = value => String(value).padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`
}

/** Format a byte count. */
export function humanBytes(value) {
  if (typeof value !== 'number' || !Number.isFinite(value)) return '—'
  if (value < 1024) return `${value} B`
  if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KiB`
  return `${(value / 1024 / 1024).toFixed(2)} MiB`
}

/** Format an integer with separators. */
export function humanNum(value) {
  return typeof value === 'number' && Number.isFinite(value) ? value.toLocaleString('en-US') : '—'
}

/**
 * Health band for the engine's 0–100 composite score.
 *
 * The engine scores each layer 0–100 and `H` is their mean, so these are
 * percentage bands. The item total is considered too: four very confident
 * entries legitimately score high while still being a young store, and calling
 * that "充盈" would overstate it.
 * @param health - Engine `H` (0–100).
 * @param total - Total entries across the four layers.
 * @returns `{ label, tone }` for the badge.
 */
export function healthBand(health, total = Number.POSITIVE_INFINITY) {
  if (typeof health !== 'number' || !Number.isFinite(health)) return { label: '未知', tone: 'idle' }
  if (health <= 0) return { label: '空仓', tone: 'idle' }
  if (health < 40 || total < 8) return { label: '稀薄', tone: 'warn' }
  if (health < 70) return { label: '成长中', tone: 'ok' }
  return { label: '充盈', tone: 'ok' }
}

/** Friendly name for one MCP server. */
export function serverLabel(server) {
  if (server === 'metago') return '元构工具集 metago'
  if (server === 'metago-algorithms') return '元构算法集 metago-algorithms'
  return server
}
